     1→#!/usr/bin/env ts-node
     2→// FreeLang v8 ML — .fl8 파일 실행기 (fl8 CLI)
     3→// Phase 6: install/publish/build 서브커맨드 추가
     4→
     5→import * as fs from "fs";
     6→import * as path from "path";
     7→import { Lexer } from "./lexer/lexer";
     8→import { Parser } from "./parser/parser";
     9→import { Interpreter } from "./runtime/interpreter";
    10→import { PackageManager } from "./pkg/package-manager";
    11→import { buildForBrowser, buildForWorker } from "./wasm/wasm_target";
    12→import { PythonBridge } from "./bridge/python_bridge";
    13→
    14→const VERSION = "8.0.0";
    15→
    16→function printHelp() {
    17→  console.log(`FreeLang v8 ML — fl8 CLI v${VERSION}
    18→
    19→사용법:
    20→  fl8                             대화형 REPL 시작
    21→  fl8 repl                        대화형 REPL 시작
    22→  fl8 <파일.fl8>                  .fl8 파일 실행
    23→  fl8 -e '<코드>'                 인라인 코드 실행
    24→
    25→패키지 관리:
    26→  fl8 init [이름]                 fl8.json 초기화
    27→  fl8 install                     모든 의존성 설치
    28→  fl8 install <패키지> [버전]     특정 패키지 설치
    29→  fl8 publish                     패키지 배포
    30→  fl8 list                        설치된 패키지 목록
    31→
    32→빌드:
    33→  fl8 build browser <입력.fl8> <출력폴더>   브라우저 번들 생성
    34→  fl8 build worker  <입력.fl8> <출력폴더>   Web Worker 번들 생성
    35→
    36→브릿지:
    37→  fl8 python info                 Python 환경 정보
    38→  fl8 python run <코드>           Python 코드 실행
    39→
    40→옵션:
    41→  --version, -v                   버전 출력
    42→  --help, -h                      이 도움말 출력`);
    43→}
    44→
    45→function main() {
    46→  const args = process.argv.slice(2);
    47→
    48→  // 인수 없이 실행하면 REPL 시작
    49→  if (args.length === 0) {
    50→    const { FL8Repl } = require('./repl/repl');
    51→    new FL8Repl().start();
    52→    return;
    53→  }
    54→
    55→  const cmd = args[0];
    56→
    57→  // repl 서브커맨드
    58→  if (cmd === "repl") {
    59→    const { FL8Repl } = require('./repl/repl');
    60→    new FL8Repl().start();
    61→    return;
    62→  }
    63→
    64→  // 버전/도움말
    65→  if (cmd === "--version" || cmd === "-v") {
    66→    console.log(`fl8 v${VERSION}`);
    67→    return;
    68→  }
    69→  if (cmd === "--help" || cmd === "-h") {
    70→    printHelp();
    71→    return;
    72→  }
    73→
    74→  // ─── 패키지 관리 ───────────────────────────────────────────
    75→
    76→  if (cmd === "init") {
    77→    const pm = new PackageManager();
    78→    const name = args[1];
    79→    try {
    80→      const manifest = pm.init(name ? { name } : {});
    81→      console.log(`✓ fl8.json 생성: ${manifest.name} v${manifest.version}`);
    82→    } catch (e: any) {
    83→      console.error("오류:", e.message);
    84→      process.exit(1);
    85→    }
    86→    return;
    87→  }
    88→
    89→  if (cmd === "install") {
    90→    const pm = new PackageManager();
    91→    const pkgName = args[1];
    92→    const version = args[2];
    93→    try {
    94→      const result = pm.install(pkgName, version);
    95→      if (result.name === "__all__") {
    96→        console.log(`✓ ${result.count ?? 0}개 패키지 설치 완료`);
    97→      } else {
    98→        console.log(`✓ ${result.name}@${result.version} 설치 완료`);
    99→        console.log(`  resolved: ${result.resolved}`);
   100→      }
   101→    } catch (e: any) {
   102→      console.error("설치 오류:", e.message);
   103→      process.exit(1);
   104→    }
   105→    return;
   106→  }
   107→
   108→  if (cmd === "publish") {
   109→    const pm = new PackageManager();
   110→    try {
   111→      const result = pm.publish();
   112→      if (result.success) {
   113→        console.log(`✓ ${result.name}@${result.version} 배포 완료`);
   114→        console.log(`  registry: ${result.registry}`);
   115→        console.log(`  파일 수: ${result.files}`);
   116→        console.log(`  URL: ${result.url}`);
   117→      }
   118→    } catch (e: any) {
   119→      console.error("배포 오류:", e.message);
   120→      process.exit(1);
   121→    }
   122→    return;
   123→  }
   124→
   125→  if (cmd === "list") {
   126→    const pm = new PackageManager();
   127→    const pkgs = pm.list();
   128→    if (pkgs.length === 0) {
   129→      console.log("설치된 패키지 없음");
   130→    } else {
   131→      console.log("패키지 목록:");
   132→      for (const pkg of pkgs) {
   133→        const status = pkg.installed ? `v${pkg.installed}` : "미설치";
   134→        console.log(`  ${pkg.name.padEnd(20)} ${pkg.required.padEnd(10)} [${status}]`);
   135→      }
   136→    }
   137→    return;
   138→  }
   139→
   140→  // ─── 빌드 ──────────────────────────────────────────────────
   141→
   142→  if (cmd === "build") {
   143→    const target = args[1]; // 'browser' | 'worker'
   144→    const entry = args[2];
   145→    const output = args[3] ?? "dist";
   146→
   147→    if (!target || !entry) {
   148→      console.error("사용법: fl8 build browser|worker <입력.fl8> <출력폴더>");
   149→      process.exit(1);
   150→    }
   151→
   152→    if (!fs.existsSync(entry)) {
   153→      console.error(`파일 없음: ${entry}`);
   154→      process.exit(1);
   155→    }
   156→
   157→    try {
   158→      let result;
   159→      if (target === "browser") {
   160→        result = buildForBrowser(entry, output);
   161→      } else if (target === "worker") {
   162→        result = buildForWorker(entry, output);
   163→      } else {
   164→        console.error(`알 수 없는 타겟: ${target} (browser|worker)`);
   165→        process.exit(1);
   166→      }
   167→
   168→      if (result.success) {
   169→        console.log(`✓ ${target} 번들 빌드 완료`);
   170→        console.log(`  출력: ${output}/`);
   171→        console.log(`  파일:`);
   172→        for (const f of result.files) {
   173→          const size = fs.statSync(f).size;
   174→          console.log(`    ${path.relative(output, f).padEnd(30)} ${(size / 1024).toFixed(1)}KB`);
   175→        }
   176→        console.log(`  총 크기: ${(result.size / 1024).toFixed(1)}KB`);
   177→      } else {
   178→        console.error("빌드 실패:", result.error);
   179→        process.exit(1);
   180→      }
   181→    } catch (e: any) {
   182→      console.error("빌드 오류:", e.message);
   183→      process.exit(1);
   184→    }
   185→    return;
   186→  }
   187→
   188→  // ─── Python 브릿지 ─────────────────────────────────────────
   189→
   190→  if (cmd === "python") {
   191→    const subCmd = args[1];
   192→    const bridge = new PythonBridge();
   193→
   194→    if (subCmd === "info") {
   195→      const available = bridge.isAvailable();
   196→      console.log(`Python: ${available ? bridge.version() : "미설치"}`);
   197→      if (available) {
   198→        console.log(`NumPy:  ${bridge.hasNumpy() ? "설치됨" : "미설치"}`);
   199→        console.log(`PyTorch: ${bridge.hasTorch() ? "설치됨" : "미설치"}`);
   200→      }
   201→      return;
   202→    }
   203→
   204→    if (subCmd === "run") {
   205→      const code = args.slice(2).join(" ");
   206→      if (!code) {
   207→        console.error("사용법: fl8 python run <Python 코드>");
   208→        process.exit(1);
   209→      }
   210→      const result = bridge.eval(code);
   211→      if (result.success) {
   212→        if (result.stdout) process.stdout.write(result.stdout);
   213→        if (result.data && Object.keys(result.data).length > 0) {
   214→          console.log("결과:", JSON.stringify(result.data, null, 2));
   215→        }
   216→      } else {
   217→        console.error("Python 오류:", result.error);
   218→        process.exit(1);
   219→      }
   220→      return;
   221→    }
   222→
   223→    console.error(`알 수 없는 python 서브커맨드: ${subCmd}`);
   224→    process.exit(1);
   225→  }
   226→
   227→  // ─── .fl8 실행 ─────────────────────────────────────────────
   228→
   229→  let source: string;
   230→  let filename: string;
   231→
   232→  if (cmd === "-e") {
   233→    source = args[1] ?? "";
   234→    filename = "<stdin>";
   235→  } else {
   236→    filename = cmd;
   237→    if (!fs.existsSync(filename)) {
   238→      console.error(`파일 없음: ${filename}`);
   239→      process.exit(1);
   240→    }
   241→    source = fs.readFileSync(filename, "utf-8");
   242→  }
   243→
   244→  // Lex
   245→  const lexer = new Lexer(source);
   246→  const { tokens, errors: lexErrors } = lexer.tokenize();
   247→
   248→  if (lexErrors.length > 0) {
   249→    for (const e of lexErrors) {
   250→      console.error(`[Lex 오류] ${filename}:${e.line}:${e.col}: ${e.message}`);
   251→    }
   252→    process.exit(1);
   253→  }
   254→
   255→  // Parse
   256→  const parser = new Parser(tokens);
   257→  const { program, errors: parseErrors } = parser.parse();
   258→
   259→  if (parseErrors.length > 0) {
   260→    for (const e of parseErrors) {
   261→      console.error(`[파서 오류] ${filename}:${e.line}:${e.col}: ${e.message}`);
   262→    }
   263→    process.exit(1);
   264→  }
   265→
   266→  // Interpret
   267→  const interp = new Interpreter();
   268→  try {
   269→    interp.run(program);
   270→  } catch (e: any) {
   271→    console.error(`[런타임 오류] ${e.message}`);
   272→    process.exit(1);
   273→  }
   274→}
   275→
   276→main();
