     1→// FreeLang v4 — Lexer (SPEC_04 구현)
     2→// UTF-8 소스코드 → 토큰 배열
     3→
     4→// ============================================================
     5→// TokenType — 6 카테고리, ~50종
     6→// ============================================================
     7→
     8→export enum TokenType {
     9→  // 키워드 (18)
    10→  VAR = "VAR",
    11→  LET = "LET",
    12→  CONST = "CONST",
    13→  FN = "FN",
    14→  STRUCT = "STRUCT",
    15→  IF = "IF",
    16→  ELSE = "ELSE",
    17→  MATCH = "MATCH",
    18→  FOR = "FOR",
    19→  IN = "IN",
    20→  OF = "OF",
    21→  WHILE = "WHILE",
    22→  BREAK = "BREAK",
    23→  CONTINUE = "CONTINUE",
    24→  RETURN = "RETURN",
    25→  SPAWN = "SPAWN",
    26→  TRUE = "TRUE",
    27→  FALSE = "FALSE",
    28→
    29→  // 타입 이름 (7)
    30→  TYPE_I32 = "TYPE_I32",
    31→  TYPE_I64 = "TYPE_I64",
    32→  TYPE_F64 = "TYPE_F64",
    33→  TYPE_BOOL = "TYPE_BOOL",
    34→  TYPE_STRING = "TYPE_STRING",
    35→  TYPE_VOID = "TYPE_VOID",
    36→  TYPE_CHANNEL = "TYPE_CHANNEL",
    37→
    38→  // 리터럴 (3)
    39→  INT_LIT = "INT_LIT",
    40→  FLOAT_LIT = "FLOAT_LIT",
    41→  STRING_LIT = "STRING_LIT",
    42→
    43→  // 연산자/구두점 (26)
    44→  PLUS = "PLUS",           // +
    45→  MINUS = "MINUS",         // -
    46→  STAR = "STAR",           // *
    47→  SLASH = "SLASH",         // /
    48→  PERCENT = "PERCENT",     // %
    49→  EQ = "EQ",               // =
    50→  EQEQ = "EQEQ",          // ==
    51→  NEQ = "NEQ",             // !=
    52→  LT = "LT",              // <
    53→  GT = "GT",               // >
    54→  LTEQ = "LTEQ",          // <=
    55→  GTEQ = "GTEQ",          // >=
    56→  AND = "AND",             // &&
    57→  OR = "OR",               // ||
    58→  NOT = "NOT",             // !
    59→  QUESTION = "QUESTION",   // ?
    60→  ARROW = "ARROW",         // =>
    61→  RARROW = "RARROW",       // ->
    62→  COLON = "COLON",         // :
    63→  COMMA = "COMMA",         // ,
    64→  DOT = "DOT",             // .
    65→  LPAREN = "LPAREN",       // (
    66→  RPAREN = "RPAREN",       // )
    67→  LBRACKET = "LBRACKET",   // [
    68→  RBRACKET = "RBRACKET",   // ]
    69→  LBRACE = "LBRACE",       // {
    70→  RBRACE = "RBRACE",       // }
    71→  SEMICOLON = "SEMICOLON", // ;
    72→
    73→  // ML 키워드 (v8 추가)
    74→  TENSOR = "TENSOR",           // tensor
    75→  GRAD = "GRAD",               // grad
    76→  WITH = "WITH",               // with
    77→  BACKWARD = "BACKWARD",       // backward
    78→  SHAPE = "SHAPE",             // shape
    79→  MATMUL = "MATMUL",           // @ (행렬곱)
    80→  TRANSPOSE = "TRANSPOSE",     // .T
    81→  TYPE_F32 = "TYPE_F32",       // f32
    82→  TYPE_TENSOR = "TYPE_TENSOR", // Tensor
    83→
    84→  // 특수 (2) — NEWLINE 토큰 없음 (SPEC_04 Q7)
    85→  IDENT = "IDENT",
    86→  EOF = "EOF",
    87→}
    88→
    89→// ============================================================
    90→// Token
    91→// ============================================================
    92→
    93→export type Token = {
    94→  type: TokenType;
    95→  lexeme: string;
    96→  line: number;
    97→  col: number;
    98→};
    99→
   100→// ============================================================
   101→// LexError
   102→// ============================================================
   103→
   104→export type LexError = {
   105→  message: string;
   106→  line: number;
   107→  col: number;
   108→};
   109→
   110→// ============================================================
   111→// 키워드 테이블 (SPEC_04 Q4)
   112→// ============================================================
   113→
   114→const KEYWORDS: Map<string, TokenType> = new Map([
   115→  // 키워드 (14)
   116→  ["var", TokenType.VAR],
   117→  ["let", TokenType.LET],
   118→  ["const", TokenType.CONST],
   119→  ["fn", TokenType.FN],
   120→  ["struct", TokenType.STRUCT],
   121→  ["if", TokenType.IF],
   122→  ["else", TokenType.ELSE],
   123→  ["match", TokenType.MATCH],
   124→  ["for", TokenType.FOR],
   125→  ["in", TokenType.IN],
   126→  ["of", TokenType.OF],
   127→  ["while", TokenType.WHILE],
   128→  ["break", TokenType.BREAK],
   129→  ["continue", TokenType.CONTINUE],
   130→  ["return", TokenType.RETURN],
   131→  ["spawn", TokenType.SPAWN],
   132→  ["true", TokenType.TRUE],
   133→  ["false", TokenType.FALSE],
   134→  // 논리 연산자 키워드 (2) — && || 대신 사용 가능
   135→  ["and", TokenType.AND],
   136→  ["or", TokenType.OR],
   137→  // 타입 이름 (7)
   138→  ["i32", TokenType.TYPE_I32],
   139→  ["i64", TokenType.TYPE_I64],
   140→  ["f64", TokenType.TYPE_F64],
   141→  ["f32", TokenType.TYPE_F32],
   142→  ["bool", TokenType.TYPE_BOOL],
   143→  ["string", TokenType.TYPE_STRING],
   144→  ["void", TokenType.TYPE_VOID],
   145→  ["channel", TokenType.TYPE_CHANNEL],
   146→  // ML 키워드 (v8)
   147→  ["tensor", TokenType.TENSOR],
   148→  ["grad", TokenType.GRAD],
   149→  ["with", TokenType.WITH],
   150→  ["backward", TokenType.BACKWARD],
   151→  ["shape", TokenType.SHAPE],
   152→  ["Tensor", TokenType.TYPE_TENSOR],
   153→]);
   154→
   155→// Option, Result, Ok, Err, Some, None은 키워드가 아님 → IDENT
   156→
   157→// ============================================================
   158→// Lexer
   159→// ============================================================
   160→
   161→export class Lexer {
   162→  private source: string;
   163→  private pos: number = 0;
   164→  private line: number = 1;
   165→  private col: number = 1;
   166→  private tokens: Token[] = [];
   167→  private errors: LexError[] = [];
   168→
   169→  constructor(source: string) {
   170→    this.source = source;
   171→  }
   172→
   173→  tokenize(): { tokens: Token[]; errors: LexError[] } {
   174→    while (!this.isAtEnd()) {
   175→      this.scanToken();
   176→    }
   177→    this.tokens.push({ type: TokenType.EOF, lexeme: "", line: this.line, col: this.col });
   178→    return { tokens: this.tokens, errors: this.errors };
   179→  }
   180→
   181→  private scanToken(): void {
   182→    const ch = this.peek();
   183→
   184→    // 공백 건너뜀 (스펙: ' ', '\t', '\r')
   185→    if (ch === " " || ch === "\t" || ch === "\r") {
   186→      this.advance();
   187→      return;
   188→    }
   189→
   190→    // 줄바꿈 — 토큰 생성 안 함, 줄 번호만 추적 (SPEC_04 Q7)
   191→    if (ch === "\n") {
   192→      this.advance();
   193→      this.line++;
   194→      this.col = 1;
   195→      return;
   196→    }
   197→
   198→    // # 주석 (FreeLang 고유)
   199→    if (ch === "#") {
   200→      this.skipHashComment();
   201→      return;
   202→    }
   203→
   204→    // 주석 또는 SLASH (SPEC_04 Q8)
   205→    if (ch === "/") {
   206→      if (this.peekNext() === "/") {
   207→        this.skipLineComment();
   208→        return;
   209→      }
   210→      if (this.peekNext() === "*") {
   211→        this.addError("block comments not supported, use //");
   212→        this.advance(); // /
   213→        this.advance(); // *
   214→        return;
   215→      }
   216→      this.addToken(TokenType.SLASH, "/");
   217→      this.advance();
   218→      return;
   219→    }
   220→
   221→    // 식별자 또는 키워드 (SPEC_04 Q4)
   222→    if (this.isAlpha(ch)) {
   223→      this.scanIdentOrKeyword();
   224→      return;
   225→    }
   226→
   227→    // 숫자 리터럴 (SPEC_04 Q5)
   228→    if (this.isDigit(ch)) {
   229→      this.scanNumber();
   230→      return;
   231→    }
   232→
   233→    // 문자열 리터럴 (SPEC_04 Q6)
   234→    if (ch === '"') {
   235→      this.scanString();
   236→      return;
   237→    }
   238→
   239→    // ML 연산자 — @ (행렬곱)
   240→    if (ch === "@") {
   241→      this.addToken(TokenType.MATMUL, "@");
   242→      this.advance();
   243→      return;
   244→    }
   245→
   246→    // 2글자 연산자 먼저 확인 (최장 일치, SPEC_04 Q3)
   247→    const startLine = this.line;
   248→    const startCol = this.col;
   249→
   250→    if (ch === "=" && this.peekNext() === "=") {
   251→      this.advance(); this.advance();
   252→      this.tokens.push({ type: TokenType.EQEQ, lexeme: "==", line: startLine, col: startCol });
   253→      return;
   254→    }
   255→    if (ch === "=" && this.peekNext() === ">") {
   256→      this.advance(); this.advance();
   257→      this.tokens.push({ type: TokenType.ARROW, lexeme: "=>", line: startLine, col: startCol });
   258→      return;
   259→    }
   260→    if (ch === "-" && this.peekNext() === ">") {
   261→      this.advance(); this.advance();
   262→      this.tokens.push({ type: TokenType.RARROW, lexeme: "->", line: startLine, col: startCol });
   263→      return;
   264→    }
   265→    if (ch === "!" && this.peekNext() === "=") {
   266→      this.advance(); this.advance();
   267→      this.tokens.push({ type: TokenType.NEQ, lexeme: "!=", line: startLine, col: startCol });
   268→      return;
   269→    }
   270→    if (ch === "<" && this.peekNext() === "=") {
   271→      this.advance(); this.advance();
   272→      this.tokens.push({ type: TokenType.LTEQ, lexeme: "<=", line: startLine, col: startCol });
   273→      return;
   274→    }
   275→    if (ch === ">" && this.peekNext() === "=") {
   276→      this.advance(); this.advance();
   277→      this.tokens.push({ type: TokenType.GTEQ, lexeme: ">=", line: startLine, col: startCol });
   278→      return;
   279→    }
   280→    if (ch === "&" && this.peekNext() === "&") {
   281→      this.advance(); this.advance();
   282→      this.tokens.push({ type: TokenType.AND, lexeme: "&&", line: startLine, col: startCol });
   283→      return;
   284→    }
   285→    if (ch === "|" && this.peekNext() === "|") {
   286→      this.advance(); this.advance();
   287→      this.tokens.push({ type: TokenType.OR, lexeme: "||", line: startLine, col: startCol });
   288→      return;
   289→    }
   290→
   291→    // ML: .T 전치 연산자
   292→    if (ch === "." && this.peekNext() === "T") {
   293→      this.advance(); this.advance();
   294→      this.tokens.push({ type: TokenType.TRANSPOSE, lexeme: ".T", line: startLine, col: startCol });
   295→      return;
   296→    }
   297→
   298→    // 1글자 연산자/구두점
   299→    const singleCharTokens: Record<string, TokenType> = {
   300→      "+": TokenType.PLUS,
   301→      "-": TokenType.MINUS,
   302→      "*": TokenType.STAR,
   303→      "%": TokenType.PERCENT,
   304→      "=": TokenType.EQ,
   305→      "<": TokenType.LT,
   306→      ">": TokenType.GT,
   307→      "!": TokenType.NOT,
   308→      "?": TokenType.QUESTION,
   309→      ":": TokenType.COLON,
   310→      ",": TokenType.COMMA,
   311→      ".": TokenType.DOT,
   312→      ";": TokenType.SEMICOLON,
   313→      "(": TokenType.LPAREN,
   314→      ")": TokenType.RPAREN,
   315→      "[": TokenType.LBRACKET,
   316→      "]": TokenType.RBRACKET,
   317→      "{": TokenType.LBRACE,
   318→      "}": TokenType.RBRACE,
   319→    };
   320→
   321→    const tokenType = singleCharTokens[ch];
   322→    if (tokenType !== undefined) {
   323→      this.addToken(tokenType, ch);
   324→      this.advance();
   325→      return;
   326→    }
   327→
   328→    // 알 수 없는 문자
   329→    this.addError(`unexpected character: ${ch}`);
   330→    this.advance();
   331→  }
   332→
   333→  // --------------------------------------------------------
   334→  // 식별자/키워드 스캔 (SPEC_04 Q4)
   335→  // --------------------------------------------------------
   336→
   337→  private scanIdentOrKeyword(): void {
   338→    const startCol = this.col;
   339→    const start = this.pos;
   340→
   341→    while (!this.isAtEnd() && this.isAlphaNum(this.peek())) {
   342→      this.advance();
   343→    }
   344→
   345→    const text = this.source.slice(start, this.pos);
   346→    const type = KEYWORDS.get(text) ?? TokenType.IDENT;
   347→    this.tokens.push({ type, lexeme: text, line: this.line, col: startCol });
   348→  }
   349→
   350→  // --------------------------------------------------------
   351→  // 숫자 스캔 (SPEC_04 Q5)
   352→  // --------------------------------------------------------
   353→
   354→  private scanNumber(): void {
   355→    const startCol = this.col;
   356→    const start = this.pos;
   357→    let isFloat = false;
   358→
   359→    // 정수부: [0-9][0-9_]*
   360→    this.consumeDigits();
   361→
   362→    // 소수점 확인: '.' 다음이 숫자면 FLOAT_LIT
   363→    if (!this.isAtEnd() && this.peek() === "." && this.isDigit(this.peekNext() ?? "")) {
   364→      isFloat = true;
   365→      this.advance(); // '.' 소비
   366→      this.consumeDigits();
   367→    }
   368→
   369→    const text = this.source.slice(start, this.pos);
   370→
   371→    // 밑줄 유효성 검사
   372→    if (text.endsWith("_")) {
   373→      this.errors.push({ message: "trailing underscore in number", line: this.line, col: startCol });
   374→      return;
   375→    }
   376→    if (text.includes("__")) {
   377→      this.errors.push({ message: "consecutive underscores in number", line: this.line, col: startCol });
   378→      return;
   379→    }
   380→
   381→    const type = isFloat ? TokenType.FLOAT_LIT : TokenType.INT_LIT;
   382→    this.tokens.push({ type, lexeme: text, line: this.line, col: startCol });
   383→  }
   384→
   385→  private consumeDigits(): void {
   386→    while (!this.isAtEnd() && (this.isDigit(this.peek()) || this.peek() === "_")) {
   387→      this.advance();
   388→    }
   389→  }
   390→
   391→  // --------------------------------------------------------
   392→  // 문자열 스캔 (SPEC_04 Q6)
   393→  // --------------------------------------------------------
   394→
   395→  private scanString(): void {
   396→    const startLine = this.line;
   397→    const startCol = this.col;
   398→    this.advance(); // 여는 '"' 소비
   399→
   400→    let value = "";
   401→
   402→    while (!this.isAtEnd() && this.peek() !== '"') {
   403→      const ch = this.peek();
   404→
   405→      // 줄바꿈 불허
   406→      if (ch === "\n") {
   407→        this.errors.push({
   408→          message: "newline in string literal, use \\n",
   409→          line: this.line,
   410→          col: this.col,
   411→        });
   412→        return;
   413→      }
   414→
   415→      // 이스케이프 시퀀스
   416→      if (ch === "\\") {
   417→        this.advance(); // '\' 소비
   418→        if (this.isAtEnd()) {
   419→          this.errors.push({ message: "unterminated string literal", line: startLine, col: startCol });
   420→          return;
   421→        }
   422→        const esc = this.peek();
   423→        switch (esc) {
   424→          case "n": value += "\n"; break;
   425→          case "t": value += "\t"; break;
   426→          case "r": value += "\r"; break;
   427→          case "\\": value += "\\"; break;
   428→          case '"': value += '"'; break;
   429→          case "0": value += "\0"; break;
   430→          default:
   431→            this.errors.push({
   432→              message: `unknown escape sequence: \\${esc}`,
   433→              line: this.line,
   434→              col: this.col - 1,
   435→            });
   436→            value += esc;
   437→        }
   438→        this.advance();
   439→        continue;
   440→      }
   441→
   442→      value += ch;
   443→      this.advance();
   444→    }
   445→
   446→    if (this.isAtEnd()) {
   447→      this.errors.push({ message: "unterminated string literal", line: startLine, col: startCol });
   448→      return;
   449→    }
   450→
   451→    this.advance(); // 닫는 '"' 소비
   452→
   453→    const lexeme = this.source.slice(this.source.indexOf('"', this.pos - value.length - 2 < 0 ? 0 : 0), this.pos);
   454→    this.tokens.push({ type: TokenType.STRING_LIT, lexeme: value, line: startLine, col: startCol });
   455→  }
   456→
   457→  // --------------------------------------------------------
   458→  // 주석 스캔 (SPEC_04 Q8)
   459→  // --------------------------------------------------------
   460→
   461→  private skipLineComment(): void {
   462→    this.advance(); // 첫 번째 '/'
   463→    this.advance(); // 두 번째 '/'
   464→    while (!this.isAtEnd() && this.peek() !== "\n") {
   465→      this.advance();
   466→    }
   467→    // '\n'은 소비하지 않음 — scanToken에서 줄 번호 처리
   468→  }
   469→
   470→  // # 주석 스캔 (FreeLang)
   471→  private skipHashComment(): void {
   472→    this.advance(); // '#' 소비
   473→    while (!this.isAtEnd() && this.peek() !== "\n") {
   474→      this.advance();
   475→    }
   476→    // '\n'은 소비하지 않음 — scanToken에서 줄 번호 처리
   477→  }
   478→
   479→  // --------------------------------------------------------
   480→  // 유틸리티
   481→  // --------------------------------------------------------
   482→
   483→  private isAtEnd(): boolean {
   484→    return this.pos >= this.source.length;
   485→  }
   486→
   487→  private peek(): string {
   488→    return this.source[this.pos];
   489→  }
   490→
   491→  private peekNext(): string | undefined {
   492→    return this.pos + 1 < this.source.length ? this.source[this.pos + 1] : undefined;
   493→  }
   494→
   495→  private advance(): void {
   496→    if (!this.isAtEnd()) {
   497→      this.pos++;
   498→      this.col++;
   499→    }
   500→  }
   501→
   502→  private isAlpha(ch: string): boolean {
   503→    return (ch >= "a" && ch <= "z") || (ch >= "A" && ch <= "Z") || ch === "_";
   504→  }
   505→
   506→  private isDigit(ch: string): boolean {
   507→    return ch >= "0" && ch <= "9";
   508→  }
   509→
   510→  private isAlphaNum(ch: string): boolean {
   511→    return this.isAlpha(ch) || this.isDigit(ch);
   512→  }
   513→
   514→  private addToken(type: TokenType, lexeme: string): void {
   515→    this.tokens.push({ type, lexeme, line: this.line, col: this.col });
   516→  }
   517→
   518→  private addError(message: string): void {
   519→    this.errors.push({ message, line: this.line, col: this.col });
   520→  }
   521→}
