    18→
    19→// ============================================================
    20→// Binding Power (SPEC_05 Q4)
    21→// ============================================================
    22→
    23→const BP_ASSIGN = 10;
    24→const BP_OR = 20;
    25→const BP_AND = 30;
    26→const BP_EQUALITY = 40;
    27→const BP_COMPARISON = 50;
    28→const BP_ADDITIVE = 60;
    29→const BP_MULTIPLICATIVE = 70;
    30→const BP_UNARY = 90;
    31→const BP_POSTFIX = 100;
    32→
    33→function infixBP(type: TokenType): number {
    34→  switch (type) {
    35→    // EQ는 Pratt에서 처리하지 않음 → ExprStmt에서 할당으로 처리
    36→    case TokenType.OR: return BP_OR;
    37→    case TokenType.AND: return BP_AND;
    38→    case TokenType.EQEQ:
    39→    case TokenType.NEQ: return BP_EQUALITY;
    40→    case TokenType.LT:
    41→    case TokenType.GT:
    42→    case TokenType.LTEQ:
    43→    case TokenType.GTEQ: return BP_COMPARISON;
    44→    case TokenType.PLUS:
    45→    case TokenType.MINUS: return BP_ADDITIVE;
    46→    case TokenType.STAR:
    47→    case TokenType.SLASH:
    48→    case TokenType.PERCENT:
    49→    case TokenType.MATMUL: return BP_MULTIPLICATIVE;
    50→    case TokenType.LPAREN:
    51→    case TokenType.LBRACKET:
    52→    case TokenType.DOT:
    53→    case TokenType.TRANSPOSE:
    54→    case TokenType.QUESTION: return BP_POSTFIX;
    55→    default: return 0;
    56→  }
    57→}
    58→
    59→// ============================================================
    60→// Parser
    61→// ============================================================
    62→
    63→export class Parser {
    64→  private tokens: Token[];
    65→  private pos: number = 0;
    66→  private errors: ParseError[] = [];
    67→
    68→  constructor(tokens: Token[]) {
    69→    this.tokens = tokens;
    70→  }
    71→
    72→  parse(): { program: Program; errors: ParseError[] } {
    73→    const stmts: Stmt[] = [];
    74→    while (!this.isAtEnd()) {
    75→      try {
    76→        stmts.push(this.parseStmt());
    77→      } catch (e) {
    78→        // 에러 복구: 다음 문 시작까지 건너뜀
    79→        this.synchronize();
    80→      }
    81→    }
    82→    return { program: { stmts }, errors: this.errors };
    83→  }
    84→
    85→  // ============================================================
    86→  // 문 파싱 — Recursive Descent (SPEC_05 Q1)
    87→  // ============================================================
    88→
    89→  private parseStmt(): Stmt {
    90→    const tok = this.peek();
    91→
    92→    switch (tok.type) {
    93→      case TokenType.VAR:
    94→      case TokenType.LET:
    95→      case TokenType.CONST:
    96→        return this.parseVarDecl();
    97→      case TokenType.FN:
    98→        return this.parseFnDecl();
    99→      case TokenType.STRUCT:
   100→        return this.parseStructDecl();

