    22→
    23→  set(id: number, t: FL8Type): void { this.map.set(id, t); }
    24→
    25→  apply(t: FL8Type): FL8Type {
    26→    if (t.tag === 'var') {
    27→      const bound = this.map.get(t.id);
    28→      return bound ? this.apply(bound) : t;
    29→    }
    30→    if (t.tag === 'array') return { ...t, elem: this.apply(t.elem) };
    31→    if (t.tag === 'fn')    return { ...t, params: t.params.map(p => this.apply(p)), ret: this.apply(t.ret) };
    32→    return t;
    33→  }
    34→
    35→  // 단일화: a ≡ b를 만족하는 대입 찾기
    36→  unify(a: FL8Type, b: FL8Type): boolean {
    37→    a = this.apply(a);
    38→    b = this.apply(b);
    39→
    40→    if (a.tag === 'unknown' || b.tag === 'unknown') return true;
    41→
    42→    if (a.tag === 'var') {
    43→      if (b.tag === 'var' && a.id === b.id) return true;
    44→      if (this.occursIn(a.id, b)) return false; // 무한 타입
    45→      this.set(a.id, b);
    46→      return true;
    47→    }
    48→    if (b.tag === 'var') return this.unify(b, a);
    49→
    50→    if (a.tag !== b.tag) return false;
    51→
    52→    if (a.tag === 'array' && b.tag === 'array')
    53→      return this.unify(a.elem, b.elem);
    54→
    55→    if (a.tag === 'fn' && b.tag === 'fn') {
    56→      if (a.params.length !== b.params.length) return false;
    57→      return a.params.every((p, i) => this.unify(p, (b as typeof a).params[i]))
    58→          && this.unify(a.ret, (b as typeof a).ret);
    59→    }
    60→
    61→    return typeEqual(a, b);
    62→  }
    63→
    64→  private occursIn(id: number, t: FL8Type): boolean {
    65→    t = this.apply(t);
    66→    if (t.tag === 'var') return t.id === id;
    67→    if (t.tag === 'array') return this.occursIn(id, t.elem);
    68→    if (t.tag === 'fn') return t.params.some(p => this.occursIn(id, p)) || this.occursIn(id, t.ret);
    69→    return false;
    70→  }
    71→}
