     3→export type TypeErrorKind =
     4→  | 'type_mismatch'
     5→  | 'undefined_variable'
     6→  | 'undefined_function'
     7→  | 'wrong_arity'
     8→  | 'not_callable'
     9→  | 'not_indexable'
    10→  | 'no_field'
