    12→  | 'tensor_shape_mismatch'
    13→  | 'infinite_type'
    14→  | 'generic_arity';
    15→
    16→export class TypeErrorReport {
    17→  readonly kind: TypeErrorKind;
    18→  readonly message: string;
    19→  readonly line: number;
    20→  readonly col: number;
    21→  readonly hint?: string;
    22→
    23→  constructor(kind: TypeErrorKind, message: string, line: number, col: number, hint?: string) {
    24→    this.kind = kind;
    25→    this.message = message;
    26→    this.line = line;
    27→    this.col = col;
    28→    this.hint = hint;
    29→  }
    30→
    31→  toString(): string {
    32→    const loc = `${this.line}:${this.col}`;
    33→    const h = this.hint ? `\n  힌트: ${this.hint}` : '';
    34→    return `[타입 오류] ${loc}: ${this.message}${h}`;
    35→  }
    36→}
    37→
    38→export class TypeError extends Error {
    39→  readonly report: TypeErrorReport;
    40→  constructor(report: TypeErrorReport) {
    41→    super(report.message);
    42→    this.report = report;
    43→  }
    44→}
    45→
    46→// 헬퍼
    47→export function typeMismatch(
    48→  expected: string, got: string,
    49→  line: number, col: number, hint?: string
    50→): TypeErrorReport {
    51→  return new TypeErrorReport(
    52→    'type_mismatch',
    53→    `타입 불일치: ${expected} 기대, ${got} 받음`,
    54→    line, col, hint
    55→  );
    56→}
    57→
    58→export function undefinedVar(name: string, line: number, col: number): TypeErrorReport {
    59→  return new TypeErrorReport(
    60→    'undefined_variable', `정의되지 않은 변수: '${name}'`, line, col,
    61→    `'let ${name} = ...'로 선언하셨나요?`
    62→  );
    63→}
    64→
    65→export function wrongArity(
    66→  name: string, expected: number, got: number,
    67→  line: number, col: number
    68→): TypeErrorReport {
    69→  return new TypeErrorReport(
    70→    'wrong_arity',
    71→    `함수 '${name}': ${expected}개 인수 필요, ${got}개 전달`,
    72→    line, col
    73→  );
    74→}
    75→
    76→export function noField(typeName: string, field: string, line: number, col: number): TypeErrorReport {
    77→  return new TypeErrorReport(
    78→    'no_field', `타입 '${typeName}'에 필드 '${field}' 없음`, line, col
    79→  );
    80→}
