// FreeLang v8 ML — LSP Language Service (Phase 13)
// 외부 LSP 라이브러리 없이 FL8 언어 서비스 엔진 구현

import { Lexer } from "../lexer/lexer";
import { Parser } from "../parser/parser";
import { TypeChecker } from "../types/type_checker";
import { Program, Stmt } from "../ast/ast";

// ============================================================
// 공용 타입 정의
// ============================================================

export interface Position {
  line: number;      // 0-based
  character: number; // 0-based
}

export interface Range {
  start: Position;
  end: Position;
}

export interface Diagnostic {
  range: Range;
  message: string;
  severity: 1 | 2 | 3; // 1=Error, 2=Warning, 3=Information
  code?: string;
}

export interface CompletionItem {
  label: string;
  kind: CompletionKind;
  detail?: string;
}

export interface HoverInfo {
  contents: string;
  range?: Range;
}

export interface SymbolInfo {
  name: string;
  kind: string;
  line: number;
}

export enum CompletionKind {
  Function = 3,
  Variable = 6,
  Keyword  = 14,
  Builtin  = 22,
}

// ============================================================
// FL8 언어 메타 정보
// ============================================================

const FL8_KEYWORDS: string[] = [
  "let", "var", "const", "fn", "if", "else", "while", "for", "in",
  "of", "return", "break", "continue", "struct", "match", "spawn",
  "true", "false", "with", "backward", "grad", "shape",
];

const FL8_BUILTIN_DOCS: Record<string, string> = {
  print:           "print(value) — 값을 출력합니다",
  len:             "len(arr) -> i32 — 배열 또는 문자열의 길이를 반환합니다",
  range:           "range(n) -> Array<i32> — 0..n 정수 배열을 생성합니다",
  push:            "push(arr, value) — 배열 끝에 값을 추가합니다",
  pop:             "pop(arr) — 배열 끝 값을 제거하고 반환합니다",
  map:             "map(arr, fn) -> Array — 배열의 각 요소에 함수를 적용합니다",
  filter:          "filter(arr, fn) -> Array — 조건을 만족하는 요소만 남깁니다",
  zeros:           "zeros(shape...) -> Tensor — 0으로 채운 텐서를 생성합니다",
  ones:            "ones(shape...) -> Tensor — 1로 채운 텐서를 생성합니다",
  randn:           "randn(shape...) -> Tensor — 정규분포 난수 텐서를 생성합니다",
  tensor:          "tensor(data, shape) -> Tensor — 데이터로 텐서를 생성합니다",
  MLP:             "MLP(layers) -> Module — 다층 퍼셉트론 모델을 생성합니다",
  Adam:            "Adam(params, lr) -> Optimizer — Adam 옵티마이저를 생성합니다",
  SGD:             "SGD(params, lr) -> Optimizer — SGD 옵티마이저를 생성합니다",
  matmul:          "matmul(a, b) -> Tensor — 행렬 곱셈을 수행합니다",
  transpose:       "transpose(t) -> Tensor — 텐서를 전치합니다",
  Linear:          "Linear(in, out) -> Module — 선형 레이어를 생성합니다",
  ReLU:            "ReLU() -> Module — ReLU 활성화 함수 레이어를 생성합니다",
  Sigmoid:         "Sigmoid() -> Module — Sigmoid 활성화 함수 레이어를 생성합니다",
  Tanh:            "Tanh() -> Module — Tanh 활성화 함수 레이어를 생성합니다",
  Softmax:         "Softmax() -> Module — Softmax 활성화 함수 레이어를 생성합니다",
  LayerNorm:       "LayerNorm(dim) -> Module — Layer Normalization 레이어를 생성합니다",
  Dropout:         "Dropout(p) -> Module — Dropout 레이어를 생성합니다",
  Sequential:      "Sequential(layers) -> Module — 레이어를 순서대로 연결합니다",
  DataLoader:      "DataLoader(data, batchSize) — 미니배치 데이터 로더를 생성합니다",
  Trainer:         "Trainer(model, optimizer, loss) — 학습 루프 관리자를 생성합니다",
  mse:             "mse(pred, target) -> f64 — 평균 제곱 오차 손실을 계산합니다",
  mae:             "mae(pred, target) -> f64 — 평균 절대 오차 손실을 계산합니다",
  assert:          "assert(cond, msg?) — 조건이 거짓이면 오류를 발생시킵니다",
  parseInt:        "parseInt(s) -> i32 — 문자열을 정수로 변환합니다",
  parseFloat:      "parseFloat(s) -> f64 — 문자열을 부동소수점으로 변환합니다",
  toString:        "toString(v) -> string — 값을 문자열로 변환합니다",
};

const FL8_KEYWORD_DOCS: Record<string, string> = {
  let:       "let name = expr — 불변 변수 선언",
  var:       "var name = expr — 가변 변수 선언",
  const:     "const name = expr — 상수 선언",
  fn:        "fn name(params) -> ReturnType { body } — 함수 선언",
  if:        "if condition { ... } else { ... } — 조건 분기",
  else:      "else { ... } — if의 거짓 분기",
  while:     "while condition { ... } — 조건 반복",
  for:       "for x in iterable { ... } — 반복자 순회",
  in:        "for x in iterable — in 키워드",
  return:    "return expr — 함수에서 값 반환",
  break:     "break — 반복문 즉시 탈출",
  continue:  "continue — 다음 반복으로 건너뜀",
  struct:    "struct Name { field: Type } — 구조체 선언",
  match:     "match expr { pattern => result } — 패턴 매칭",
  true:      "bool 리터럴: 참",
  false:     "bool 리터럴: 거짓",
  with:      "with grad: { ... } — 자동 미분 블록",
  backward:  "backward() — 역전파 실행",
  grad:      "grad — 자동 미분 컨텍스트",
};

// ============================================================
// 내부 유틸리티
// ============================================================

/**
 * 소스 코드에서 주어진 0-based 줄/칼럼 위치에 있는 단어를 추출한다.
 */
function getWordAt(source: string, pos: Position): { word: string; start: number; end: number } | null {
  const lines = source.split("\n");
  if (pos.line >= lines.length) return null;
  const line = lines[pos.line];
  if (pos.character > line.length) return null;

  // 식별자 문자: [a-zA-Z_][a-zA-Z0-9_]*
  const isIdentChar = (c: string) => /[a-zA-Z0-9_]/.test(c);

  let start = pos.character;
  while (start > 0 && isIdentChar(line[start - 1])) start--;

  let end = pos.character;
  while (end < line.length && isIdentChar(line[end])) end++;

  if (start === end) return null;

  return { word: line.slice(start, end), start, end };
}

/**
 * 렉서/파서/타입 체커 오류를 Diagnostic 배열로 변환한다.
 * line/col은 1-based이므로 0-based로 변환한다.
 */
function toDiagnosticRange(line: number, col: number): Range {
  const l = Math.max(0, line - 1);
  const c = Math.max(0, col - 1);
  return { start: { line: l, character: c }, end: { line: l, character: c + 1 } };
}

/**
 * 소스에서 사용자 정의 식별자(변수/함수명)를 수집한다.
 */
function collectUserSymbols(program: Program): SymbolInfo[] {
  const symbols: SymbolInfo[] = [];

  function visitStmt(stmt: Stmt): void {
    if (stmt.kind === "var_decl") {
      symbols.push({ name: stmt.name, kind: "Variable", line: stmt.line - 1 });
    } else if (stmt.kind === "fn_decl") {
      symbols.push({ name: stmt.name, kind: "Function", line: stmt.line - 1 });
      for (const s of stmt.body) visitStmt(s);
    } else if (stmt.kind === "struct_decl") {
      symbols.push({ name: stmt.name, kind: "Struct", line: stmt.line - 1 });
    } else if (stmt.kind === "if_stmt") {
      for (const s of stmt.then) visitStmt(s);
      if (stmt.else_) for (const s of stmt.else_) visitStmt(s);
    } else if (stmt.kind === "while_stmt") {
      for (const s of stmt.body) visitStmt(s);
    } else if (stmt.kind === "for_stmt" || stmt.kind === "for_of_stmt") {
      for (const s of stmt.body) visitStmt(s);
    }
  }

  for (const stmt of program.stmts) visitStmt(stmt);
  return symbols;
}

/**
 * 소스에서 변수/함수 선언 위치를 이름 기준으로 반환한다 (0-based line/col).
 */
function findDefinitionPos(program: Program, name: string): Position | null {
  function searchStmts(stmts: Stmt[]): Position | null {
    for (const stmt of stmts) {
      if (stmt.kind === "var_decl" && stmt.name === name) {
        return { line: stmt.line - 1, character: stmt.col - 1 };
      }
      if (stmt.kind === "fn_decl" && stmt.name === name) {
        return { line: stmt.line - 1, character: stmt.col - 1 };
      }
      if (stmt.kind === "fn_decl") {
        const inner = searchStmts(stmt.body);
        if (inner) return inner;
      }
      if (stmt.kind === "if_stmt") {
        const t = searchStmts(stmt.then);
        if (t) return t;
        if (stmt.else_) {
          const e = searchStmts(stmt.else_);
          if (e) return e;
        }
      }
      if (stmt.kind === "while_stmt") {
        const w = searchStmts(stmt.body);
        if (w) return w;
      }
      if (stmt.kind === "for_stmt" || stmt.kind === "for_of_stmt") {
        const f = searchStmts(stmt.body);
        if (f) return f;
      }
    }
    return null;
  }
  return searchStmts(program.stmts);
}

// ============================================================
// FL8LanguageService
// ============================================================

export class FL8LanguageService {

  // ----------------------------------------------------------
  // getDiagnostics — 렉서 + 파서 + 타입 체커 오류를 수집한다
  // ----------------------------------------------------------

  getDiagnostics(source: string): Diagnostic[] {
    const diagnostics: Diagnostic[] = [];

    // 1. Lex
    const lexer = new Lexer(source);
    const { tokens, errors: lexErrors } = lexer.tokenize();

    for (const e of lexErrors) {
      diagnostics.push({
        range: toDiagnosticRange(e.line, e.col),
        message: e.message,
        severity: 1,
        code: "lex-error",
      });
    }

    if (lexErrors.length > 0) {
      // 렉서 오류가 있으면 파서가 의미 없는 오류를 낼 수 있으므로 여기서 반환
      return diagnostics;
    }

    // 2. Parse
    const parser = new Parser(tokens);
    const { program, errors: parseErrors } = parser.parse();

    for (const e of parseErrors) {
      diagnostics.push({
        range: toDiagnosticRange(e.line, e.col),
        message: e.message,
        severity: 1,
        code: "parse-error",
      });
    }

    // 3. Type Check
    try {
      const checker = new TypeChecker();
      checker.check(program);

      for (const e of checker.errors) {
        diagnostics.push({
          range: toDiagnosticRange(e.line, e.col),
          message: e.message,
          severity: 1,
          code: e.kind,
        });
      }
    } catch {
      // 타입 체커 내부 예외는 무시 (파서 오류가 있으면 발생할 수 있음)
    }

    return diagnostics;
  }

  // ----------------------------------------------------------
  // getCompletions — 커서 위치 기반 자동완성
  // ----------------------------------------------------------

  getCompletions(source: string, pos: Position): CompletionItem[] {
    const items: CompletionItem[] = [];

    // 커서 앞의 현재 단어(접두사) 추출
    const lines = source.split("\n");
    let prefix = "";
    if (pos.line < lines.length) {
      const line = lines[pos.line];
      let i = pos.character;
      while (i > 0 && /[a-zA-Z0-9_]/.test(line[i - 1])) i--;
      prefix = line.slice(i, pos.character);
    }

    const lp = prefix.toLowerCase();
    const matchPrefix = (word: string) =>
      prefix === "" || word.toLowerCase().startsWith(lp);

    // 키워드 제안
    for (const kw of FL8_KEYWORDS) {
      if (matchPrefix(kw)) {
        items.push({ label: kw, kind: CompletionKind.Keyword, detail: "keyword" });
      }
    }

    // 빌트인 함수 제안
    for (const name of Object.keys(FL8_BUILTIN_DOCS)) {
      if (matchPrefix(name)) {
        items.push({ label: name, kind: CompletionKind.Builtin, detail: FL8_BUILTIN_DOCS[name] });
      }
    }

    // 사용자 정의 변수/함수 제안 (파서가 성공하면)
    try {
      const lexer = new Lexer(source);
      const { tokens, errors: lexErrors } = lexer.tokenize();
      if (lexErrors.length === 0) {
        const parser = new Parser(tokens);
        const { program } = parser.parse();
        const userSymbols = collectUserSymbols(program);
        const builtinNames = new Set(Object.keys(FL8_BUILTIN_DOCS));
        const kwSet = new Set(FL8_KEYWORDS);
        for (const sym of userSymbols) {
          if (!builtinNames.has(sym.name) && !kwSet.has(sym.name) && matchPrefix(sym.name)) {
            items.push({
              label: sym.name,
              kind: sym.kind === "Function" ? CompletionKind.Function : CompletionKind.Variable,
              detail: `user ${sym.kind.toLowerCase()}`,
            });
          }
        }
      }
    } catch {
      // 파싱 실패 시 사용자 심볼 제안 생략
    }

    // 중복 제거 (label 기준)
    const seen = new Set<string>();
    return items.filter(item => {
      if (seen.has(item.label)) return false;
      seen.add(item.label);
      return true;
    });
  }

  // ----------------------------------------------------------
  // getHover — 커서 아래 단어의 설명 반환
  // ----------------------------------------------------------

  getHover(source: string, pos: Position): HoverInfo | null {
    const wordInfo = getWordAt(source, pos);
    if (!wordInfo) return null;

    const { word, start, end } = wordInfo;
    const range: Range = {
      start: { line: pos.line, character: start },
      end:   { line: pos.line, character: end },
    };

    // 키워드
    if (FL8_KEYWORD_DOCS[word]) {
      return { contents: FL8_KEYWORD_DOCS[word], range };
    }

    // 빌트인 함수
    if (FL8_BUILTIN_DOCS[word]) {
      return { contents: FL8_BUILTIN_DOCS[word], range };
    }

    return null;
  }

  // ----------------------------------------------------------
  // getSymbols — 문서 심볼 목록 (함수/변수/구조체 선언)
  // ----------------------------------------------------------

  getSymbols(source: string): SymbolInfo[] {
    try {
      const lexer = new Lexer(source);
      const { tokens, errors: lexErrors } = lexer.tokenize();
      if (lexErrors.length > 0) return [];

      const parser = new Parser(tokens);
      const { program } = parser.parse();

      return collectUserSymbols(program);
    } catch {
      return [];
    }
  }

  // ----------------------------------------------------------
  // getDefinition — 커서 위치 식별자의 선언 위치 반환
  // ----------------------------------------------------------

  getDefinition(source: string, pos: Position): Position | null {
    const wordInfo = getWordAt(source, pos);
    if (!wordInfo) return null;

    const { word } = wordInfo;

    try {
      const lexer = new Lexer(source);
      const { tokens, errors: lexErrors } = lexer.tokenize();
      if (lexErrors.length > 0) return null;

      const parser = new Parser(tokens);
      const { program } = parser.parse();

      return findDefinitionPos(program, word);
    } catch {
      return null;
    }
  }

  // ----------------------------------------------------------
  // format — 기본 인덴트 정규화 (2스페이스)
  // ----------------------------------------------------------

  format(source: string): string {
    const lines = source.split("\n");
    let indentLevel = 0;
    const result: string[] = [];

    for (const rawLine of lines) {
      const trimmed = rawLine.trim();

      // 빈 줄은 그대로
      if (trimmed === "") {
        result.push("");
        continue;
      }

      // 닫는 괄호로 시작하면 들여쓰기 먼저 감소
      const closingBraces = (trimmed.match(/^[}\]]/g) || []).length;
      indentLevel = Math.max(0, indentLevel - closingBraces);

      const indent = "  ".repeat(indentLevel);
      result.push(indent + trimmed);

      // 여는 괄호 수 - 닫는 괄호 수만큼 레벨 증가 (줄 전체 기준)
      const opens  = (trimmed.match(/[{[]/g) || []).length;
      const closes = (trimmed.match(/[}\]]/g) || []).length;
      indentLevel = Math.max(0, indentLevel + opens - closes + closingBraces);
    }

    return result.join("\n");
  }
}

