    console.log(`✓ ${filename}: 오류 없음`);
  } else {
    const severityLabel = (s: 1 | 2 | 3) =>
      s === 1 ? "오류" : s === 2 ? "경고" : "정보";
    for (const d of diagnostics) {
      const loc = `${d.range.start.line + 1}:${d.range.start.character + 1}`;
      const code = d.code ? ` [${d.code}]` : "";
      console.error(`${filename}:${loc}: ${severityLabel(d.severity)}${code}: ${d.message}`);
    }
    process.exit(1);
  }
  return;
}

