#!/usr/bin/env ts-node
// FreeLang v8 ML — Phase 13 LSP Language Service Tests
// 25개 이상 테스트

import {
  FL8LanguageService,
  CompletionKind,
  Diagnostic,
  CompletionItem,
  HoverInfo,
  SymbolInfo,
  Position,
} from "../src/lsp/language_service";

// ============================================================
// 테스트 러너
// ============================================================

let passed = 0;
let failed = 0;
const failures: string[] = [];

function test(name: string, fn: () => void): void {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.error(`  ✗ ${name}`);
    console.error(`      ${e.message}`);
    failures.push(name);
    failed++;
  }
}

function assert(condition: boolean, msg: string): void {
  if (!condition) throw new Error(msg);
}

function assertEqual<T>(actual: T, expected: T, msg?: string): void {
  if (actual !== expected) {
    throw new Error(
      `${msg ?? "값 불일치"}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`
    );
  }
}

function assertIncludes<T>(arr: T[], item: T, msg?: string): void {
  if (!arr.includes(item)) {
    throw new Error(`${msg ?? "포함 실패"}: ${JSON.stringify(item)} not in ${JSON.stringify(arr)}`);
  }
}

const svc = new FL8LanguageService();

// ============================================================
// 1. getDiagnostics
// ============================================================

console.log("\n[1] getDiagnostics");

test("getDiagnostics — 오류 없는 소스는 빈 배열", () => {
  const src = `let x = 42\nlet y = "hello"\n`;
  const diags = svc.getDiagnostics(src);
  assertEqual(diags.length, 0, "진단 수");
});

test("getDiagnostics — 파서 오류 감지", () => {
  // fn 선언에 -> 없으면 파서 오류
  const src = `fn foo() { let x = 1 }`;
  const diags = svc.getDiagnostics(src);
  assert(diags.length > 0, "파서 오류가 없음");
  assertEqual(diags[0].severity, 1, "오류 severity=1");
});

test("getDiagnostics — 타입 오류 감지", () => {
  // 타입 불일치: i32 선언에 문자열 대입
  const src = `let x: i32 = "hello"`;
  const diags = svc.getDiagnostics(src);
  assert(diags.length > 0, "타입 오류가 없음");
});

test("getDiagnostics — range가 올바른 구조", () => {
  const src = `fn bad( { }`;
  const diags = svc.getDiagnostics(src);
  assert(diags.length > 0, "진단이 없음");
  const d = diags[0];
  assert(typeof d.range.start.line === "number", "start.line 없음");
  assert(typeof d.range.start.character === "number", "start.character 없음");
});

test("getDiagnostics — code 필드가 문자열", () => {
  const src = `fn bad( { }`;
  const diags = svc.getDiagnostics(src);
  assert(diags.length > 0, "진단이 없음");
  assert(typeof diags[0].code === "string", "code가 string이 아님");
});

test("getDiagnostics — 빈 소스는 오류 없음", () => {
  const diags = svc.getDiagnostics("");
  assertEqual(diags.length, 0, "빈 소스에서 오류 발생");
});

test("getDiagnostics — 여러 오류 수집", () => {
  // 두 개의 잘못된 선언
  const src = `let = 1\nlet = 2`;
  const diags = svc.getDiagnostics(src);
  assert(diags.length >= 1, "복수 오류 미감지");
});

// ============================================================
// 2. getCompletions
// ============================================================

console.log("\n[2] getCompletions");

test("getCompletions — 빈 소스에서 키워드 포함", () => {
  const items = svc.getCompletions("", { line: 0, character: 0 });
  const labels = items.map(i => i.label);
  assertIncludes(labels, "let", "let 키워드 없음");
  assertIncludes(labels, "fn", "fn 키워드 없음");
  assertIncludes(labels, "if", "if 키워드 없음");
});

test("getCompletions — 빌트인 함수 포함", () => {
  const items = svc.getCompletions("", { line: 0, character: 0 });
  const labels = items.map(i => i.label);
  assertIncludes(labels, "print", "print 없음");
  assertIncludes(labels, "zeros", "zeros 없음");
  assertIncludes(labels, "MLP", "MLP 없음");
});

test("getCompletions — 키워드 접두사 필터링", () => {
  const src = "le";
  const items = svc.getCompletions(src, { line: 0, character: 2 });
  const labels = items.map(i => i.label);
  assertIncludes(labels, "let", "'let' 미포함");
  assert(!labels.includes("fn"), "'fn'이 포함되면 안 됨");
});

test("getCompletions — 빌트인 접두사 필터링 (pr)", () => {
  const src = "pr";
  const items = svc.getCompletions(src, { line: 0, character: 2 });
  const labels = items.map(i => i.label);
  assertIncludes(labels, "print", "print 미포함");
});

test("getCompletions — 사용자 정의 변수 제안", () => {
  const src = `let myVar = 10\n`;
  const items = svc.getCompletions(src, { line: 1, character: 0 });
  const labels = items.map(i => i.label);
  assertIncludes(labels, "myVar", "사용자 변수 미제안");
});

test("getCompletions — 사용자 정의 함수 제안", () => {
  const src = `fn myFunc(x: i32) -> i32 { return x }\n`;
  const items = svc.getCompletions(src, { line: 1, character: 0 });
  const labels = items.map(i => i.label);
  assertIncludes(labels, "myFunc", "사용자 함수 미제안");
});

test("getCompletions — CompletionKind 타입 확인", () => {
  const items = svc.getCompletions("", { line: 0, character: 0 });
  const fnItem = items.find(i => i.label === "fn");
  assert(fnItem !== undefined, "fn 키워드 없음");
  assertEqual(fnItem!.kind, CompletionKind.Keyword, "fn은 Keyword 종류여야 함");

  const printItem = items.find(i => i.label === "print");
  assert(printItem !== undefined, "print 없음");
  assertEqual(printItem!.kind, CompletionKind.Builtin, "print는 Builtin 종류여야 함");
});

test("getCompletions — ML 빌트인 포함 (Adam, SGD)", () => {
  const items = svc.getCompletions("", { line: 0, character: 0 });
  const labels = items.map(i => i.label);
  assertIncludes(labels, "Adam", "Adam 없음");
  assertIncludes(labels, "SGD", "SGD 없음");
  assertIncludes(labels, "matmul", "matmul 없음");
});

test("getCompletions — 중복 없음", () => {
  const items = svc.getCompletions("", { line: 0, character: 0 });
  const labels = items.map(i => i.label);
  const unique = new Set(labels);
  assertEqual(unique.size, labels.length, "중복된 completion item 존재");
});

// ============================================================
// 3. getHover
// ============================================================

console.log("\n[3] getHover");

test("getHover — 키워드(let)에 설명 반환", () => {
  const src = "let x = 1";
  const hover = svc.getHover(src, { line: 0, character: 1 });
  assert(hover !== null, "hover가 null");
  assert(hover!.contents.includes("let"), "contents에 let 없음");
});

test("getHover — 빌트인(print)에 설명 반환", () => {
  const src = "print(42)";
  const hover = svc.getHover(src, { line: 0, character: 2 });
  assert(hover !== null, "hover가 null");
  assert(hover!.contents.includes("print"), "contents에 print 없음");
});

test("getHover — 알 수 없는 식별자는 null", () => {
  const src = "unknownIdent";
  const hover = svc.getHover(src, { line: 0, character: 4 });
  assertEqual(hover, null, "알 수 없는 식별자에 hover 반환됨");
});

test("getHover — range 필드 포함", () => {
  const src = "fn foo() -> void {}";
  const hover = svc.getHover(src, { line: 0, character: 1 });
  assert(hover !== null, "hover null");
  assert(hover!.range !== undefined, "range 없음");
  assertEqual(hover!.range!.start.line, 0, "range.start.line 오류");
});

test("getHover — ML 키워드(zeros) 설명 반환", () => {
  const src = "zeros(3, 3)";
  const hover = svc.getHover(src, { line: 0, character: 2 });
  assert(hover !== null, "hover null");
  assert(hover!.contents.includes("Tensor"), "Tensor 설명 없음");
});

// ============================================================
// 4. getSymbols
// ============================================================

console.log("\n[4] getSymbols");

test("getSymbols — 함수 선언 추출", () => {
  const src = `fn add(x: i32, y: i32) -> i32 { return x }\n`;
  const symbols = svc.getSymbols(src);
  const names = symbols.map(s => s.name);
  assertIncludes(names, "add", "add 함수 미추출");
  const sym = symbols.find(s => s.name === "add")!;
  assertEqual(sym.kind, "Function", "kind가 Function이 아님");
});

test("getSymbols — 변수 선언 추출", () => {
  const src = `let counter = 0\nlet name = "fl8"\n`;
  const symbols = svc.getSymbols(src);
  const names = symbols.map(s => s.name);
  assertIncludes(names, "counter", "counter 미추출");
  assertIncludes(names, "name", "name 미추출");
});

test("getSymbols — line 번호는 0-based", () => {
  const src = `let x = 1\nfn foo() -> void { }\n`;
  const symbols = svc.getSymbols(src);
  const x = symbols.find(s => s.name === "x")!;
  assertEqual(x.line, 0, "x는 0번 줄이어야 함");
  const foo = symbols.find(s => s.name === "foo")!;
  assertEqual(foo.line, 1, "foo는 1번 줄이어야 함");
});

test("getSymbols — 빈 소스에서 빈 배열", () => {
  const symbols = svc.getSymbols("");
  assertEqual(symbols.length, 0, "빈 소스에서 심볼 반환됨");
});

// ============================================================
// 5. getDefinition
// ============================================================

console.log("\n[5] getDefinition");

test("getDefinition — 변수 사용 위치 → 선언 위치", () => {
  const src = `let myVal = 100\nprint(myVal)\n`;
  // myVal 사용은 두 번째 줄
  const pos = svc.getDefinition(src, { line: 1, character: 7 });
  assert(pos !== null, "definition이 null");
  assertEqual(pos!.line, 0, "선언 줄이 0이어야 함");
});

test("getDefinition — 함수 사용 위치 → 선언 위치", () => {
  const src = `fn compute() -> i32 { return 42 }\nlet r = compute()\n`;
  const pos = svc.getDefinition(src, { line: 1, character: 10 });
  assert(pos !== null, "definition이 null");
  assertEqual(pos!.line, 0, "함수 선언 줄이 0이어야 함");
});

test("getDefinition — 알 수 없는 이름은 null", () => {
  const src = `let x = 1\nprint(unknown)\n`;
  const pos = svc.getDefinition(src, { line: 1, character: 7 });
  assertEqual(pos, null, "알 수 없는 이름에 정의 위치 반환");
});

// ============================================================
// 6. format
// ============================================================

console.log("\n[6] format");

test("format — 들여쓰기 정규화 (2스페이스)", () => {
  const src = `fn foo() -> void {\nlet x = 1\n}`;
  const formatted = svc.format(src);
  const lines = formatted.split("\n");
  // 두 번째 줄은 2칸 들여쓰기
  assert(lines[1].startsWith("  "), `들여쓰기 없음: "${lines[1]}"`);
  // 닫는 중괄호는 들여쓰기 없어야 함
  assert(!lines[2].startsWith("  "), `닫는 중괄호 들여쓰기 오류: "${lines[2]}"`);
});

test("format — 빈 줄 유지", () => {
  const src = `let x = 1\n\nlet y = 2`;
  const formatted = svc.format(src);
  const lines = formatted.split("\n");
  assertEqual(lines[1], "", "빈 줄이 유지되어야 함");
});

test("format — 이미 올바른 형식은 변경 없음", () => {
  const src = `let x = 1`;
  const formatted = svc.format(src);
  assertEqual(formatted.trim(), src.trim(), "단순 소스 변경됨");
});

test("format — 중첩 블록 들여쓰기", () => {
  const src = `fn outer() -> void {\nif true {\nlet z = 0\n}\n}`;
  const formatted = svc.format(src);
  const lines = formatted.split("\n");
  // 'if true {' → 2칸
  assert(lines[1].startsWith("  "), `if 줄 들여쓰기 없음: "${lines[1]}"`);
  // 'let z = 0' → 4칸
  assert(lines[2].startsWith("    "), `내부 줄 들여쓰기 없음: "${lines[2]}"`);
  // '}' (if 닫기) → 2칸
  assert(lines[3].startsWith("  "), `if 닫기 들여쓰기 없음: "${lines[3]}"`);
});

// ============================================================
// 결과
// ============================================================

console.log(`\n${"─".repeat(50)}`);
console.log(`Phase 13 LSP: ${passed} PASS, ${failed} FAIL`);
if (failures.length > 0) {
  console.error("실패한 테스트:");
  for (const f of failures) console.error(`  - ${f}`);
  process.exit(1);
} else {
  console.log("모든 테스트 통과!");
}
